def count_valid_joke_sets(N, jokes, supervisors):
    tree = defaultdict(list)
    for a, b in supervisors:
        tree[b].append(a)

    dp = [{} for _ in range(N + 1)]

    def dfs(node):
        if not tree[node]:
            dp[node][jokes[node - 1]] = 1
            return

        product = 1
        for child in tree[node]:
            dfs(child)
            child_sums = sum(dp[child].values())
            product *= child_sums

        for joke in range(1, 101):
            dp[node][joke] = product

        for child in tree[node]:
            child_joke = jokes[child - 1]
            for parent_joke in range(1, 101):
                if abs(parent_joke - child_joke) != 1:
                    dp[node][parent_joke] -= dp[child][child_joke]

        dp[node] = {k: v for k, v in dp[node].items() if v > 0}

    dfs(1)
    return sum(dp[1].values())

