import sys
from collections import defaultdict, deque

def count_valid_joke_sets():
    input = sys.stdin.readline

    N = int(input().strip())
    V = [0] + list(map(int, input().strip().split()))

    subordinates = defaultdict(list)
    for _ in range(N - 1):
        A, B = map(int, input().strip().split())
        subordinates[A].append(B)

    def is_consecutive(joke_set):
        if len(joke_set) <= 1:
            return True
        sorted_set = sorted(joke_set)
        for i in range(1, len(sorted_set)):
            if sorted_set[i] != sorted_set[i - 1] + 1:
                return False
        return True

    def dfs(node, visited, parent_jokes):
        visited[node] = True
        current_jokes = set(parent_jokes)
        current_jokes.add(V[node])

        if len(current_jokes) != len(parent_jokes) + 1:
            return 0

        total_count = 1
        for subordinate in subordinates[node]:
            if not visited[subordinate]:
                if is_consecutive(current_jokes):
                    total_count += dfs(subordinate, visited, current_jokes)

        return total_count

    visited = [False] * (N + 1)
    result = dfs(1, visited, set())
    print(result)

